insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015100','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001501','multiple_choice','easy','published','A parábola $f(x)=-(x--1)^2+3$ representa uma grandeza para todo $x\in\mathbb R$. Em que ponto ocorre seu máximo global?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
