insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000151001','00000043-0000-4000-8000-000000015100','Observe o sinal do termo quadrático.',1),('00000063-0000-4000-8000-000000151002','00000043-0000-4000-8000-000000015100','A forma de vértice já mostra a abscissa do extremo.',2),('00000063-0000-4000-8000-000000151003','00000043-0000-4000-8000-000000015100','Substitua a abscissa do vértice na expressão para conferir a ordenada.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015100','$(-1,3)$','Esta questão avalia localizar o máximo de uma parábola. A expressão está na forma de vértice: $f(x)=-(x--1)^2+3$. O termo x+1 se anula em $x=-1$. O coeficiente de $(x-v)^2$ é negativo, portanto a parábola abre para baixo. No vértice, o termo quadrático vale zero e $f(-1)=3$. Todos os outros valores subtraem um quadrado de $k$, logo não podem ser maiores. A conclusão é $(-1,3)$; os demais resultados correspondem a trocar o sinal da abscissa ou ignorar a concavidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000151001','00000043-0000-4000-8000-000000015100','Identifique a forma','A expressão está na forma de vértice: $f(x)=-(x--1)^2+3$.',1),('00000073-0000-4000-8000-000000151002','00000043-0000-4000-8000-000000015100','Localize o vértice','O termo x+1 se anula em $x=-1$.',2),('00000073-0000-4000-8000-000000151003','00000043-0000-4000-8000-000000015100','Classifique a concavidade','O coeficiente de $(x-v)^2$ é negativo, portanto a parábola abre para baixo.',3),('00000073-0000-4000-8000-000000151004','00000043-0000-4000-8000-000000015100','Calcule a altura','No vértice, o termo quadrático vale zero e $f(-1)=3$.',4),('00000073-0000-4000-8000-000000151005','00000043-0000-4000-8000-000000015100','Verifique','Todos os outros valores subtraem um quadrado de $k$, logo não podem ser maiores.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
