insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015105','$(4,7)$','Esta questão avalia localizar o máximo de uma parábola. A expressão está na forma de vértice: $f(x)=-(x-4)^2+7$. O termo x-4 se anula em $x=4$. O coeficiente de $(x-v)^2$ é negativo, portanto a parábola abre para baixo. No vértice, o termo quadrático vale zero e $f(4)=7$. Todos os outros valores subtraem um quadrado de $k$, logo não podem ser maiores. A conclusão é $(4,7)$; os demais resultados correspondem a trocar o sinal da abscissa ou ignorar a concavidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000151051','00000043-0000-4000-8000-000000015105','Identifique a forma','A expressão está na forma de vértice: $f(x)=-(x-4)^2+7$.',1),('00000073-0000-4000-8000-000000151052','00000043-0000-4000-8000-000000015105','Localize o vértice','O termo x-4 se anula em $x=4$.',2),('00000073-0000-4000-8000-000000151053','00000043-0000-4000-8000-000000015105','Classifique a concavidade','O coeficiente de $(x-v)^2$ é negativo, portanto a parábola abre para baixo.',3),('00000073-0000-4000-8000-000000151054','00000043-0000-4000-8000-000000015105','Calcule a altura','No vértice, o termo quadrático vale zero e $f(4)=7$.',4),('00000073-0000-4000-8000-000000151055','00000043-0000-4000-8000-000000015105','Verifique','Todos os outros valores subtraem um quadrado de $k$, logo não podem ser maiores.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
