insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015106','$(-2,6)$','Esta questão avalia localizar o máximo de uma parábola. A expressão está na forma de vértice: $f(x)=-(x--2)^2+6$. O termo x+2 se anula em $x=-2$. O coeficiente de $(x-v)^2$ é negativo, portanto a parábola abre para baixo. No vértice, o termo quadrático vale zero e $f(-2)=6$. Todos os outros valores subtraem um quadrado de $k$, logo não podem ser maiores. A conclusão é $(-2,6)$; os demais resultados correspondem a trocar o sinal da abscissa ou ignorar a concavidade.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
