insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015108','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001501','multiple_choice','medium','published','Determine os valores mínimo e máximo absolutos de $f(x)=x^2-4x+1$ no intervalo fechado $[0,5]$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000151081','00000043-0000-4000-8000-000000015108','A','mínimo $-3$ e máximo $6$',1),('00000053-0000-4000-8000-000000151082','00000043-0000-4000-8000-000000015108','B','mínimo $6$ e máximo $-3$',2),('00000053-0000-4000-8000-000000151083','00000043-0000-4000-8000-000000015108','C','mínimo $1$ e máximo $6$',3),('00000053-0000-4000-8000-000000151084','00000043-0000-4000-8000-000000015108','D','não há extremos absolutos',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
