insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000151081','00000043-0000-4000-8000-000000015108','Em intervalo fechado, compare críticos internos e extremidades.',1),('00000063-0000-4000-8000-000000151082','00000043-0000-4000-8000-000000015108','Derive a função e resolva $f^{\prime}(x)=0$.',2),('00000063-0000-4000-8000-000000151083','00000043-0000-4000-8000-000000015108','Monte uma tabela com os valores nos candidatos; nesta questão, eles são $(-3,1,6)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015108','mínimo $-3$ e máximo $6$','Esta questão avalia comparar candidatos de extremo absoluto. Um polinômio é contínuo; em um intervalo fechado ele atinge máximo e mínimo absolutos. A derivada é linear e seu zero fornece o vértice, quando ele pertence ao intervalo. Avalie também os dois extremos do intervalo. Os valores relevantes são $(-3,1,6)$. O menor valor é $-3$ e o maior é $6$. A comparação inclui todos os únicos candidatos possíveis, portanto a classificação é absoluta. A conclusão é mínimo $-3$ e máximo $6$; os demais resultados correspondem a considerar somente o ponto crítico ou somente as extremidades.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000151081','00000043-0000-4000-8000-000000015108','Use o Teorema do Valor Extremo','Um polinômio é contínuo; em um intervalo fechado ele atinge máximo e mínimo absolutos.',1),('00000073-0000-4000-8000-000000151082','00000043-0000-4000-8000-000000015108','Encontre candidatos internos','A derivada é linear e seu zero fornece o vértice, quando ele pertence ao intervalo.',2),('00000073-0000-4000-8000-000000151083','00000043-0000-4000-8000-000000015108','Inclua as extremidades','Avalie também os dois extremos do intervalo. Os valores relevantes são $(-3,1,6)$.',3),('00000073-0000-4000-8000-000000151084','00000043-0000-4000-8000-000000015108','Compare os valores','O menor valor é $-3$ e o maior é $6$.',4),('00000073-0000-4000-8000-000000151085','00000043-0000-4000-8000-000000015108','Conclua','A comparação inclui todos os únicos candidatos possíveis, portanto a classificação é absoluta.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
