insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000151111','00000043-0000-4000-8000-000000015111','Em intervalo fechado, compare críticos internos e extremidades.',1),('00000063-0000-4000-8000-000000151112','00000043-0000-4000-8000-000000015111','Derive a função e resolva $f^{\prime}(x)=0$.',2),('00000063-0000-4000-8000-000000151113','00000043-0000-4000-8000-000000015111','Monte uma tabela com os valores nos candidatos; nesta questão, eles são $(-4,0,5)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015111','mínimo $-4$ e máximo $5$','Esta questão avalia comparar candidatos de extremo absoluto. Um polinômio é contínuo; em um intervalo fechado ele atinge máximo e mínimo absolutos. A derivada é linear e seu zero fornece o vértice, quando ele pertence ao intervalo. Avalie também os dois extremos do intervalo. Os valores relevantes são $(-4,0,5)$. O menor valor é $-4$ e o maior é $5$. A comparação inclui todos os únicos candidatos possíveis, portanto a classificação é absoluta. A conclusão é mínimo $-4$ e máximo $5$; os demais resultados correspondem a considerar somente o ponto crítico ou somente as extremidades.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
