insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000151161','00000043-0000-4000-8000-000000015116','Número crítico não é automaticamente máximo ou mínimo.',1),('00000063-0000-4000-8000-000000151162','00000043-0000-4000-8000-000000015116','Faça uma tabela de sinais para $f^{\prime}$ nos intervalos separados pelos críticos.',2),('00000063-0000-4000-8000-000000151163','00000043-0000-4000-8000-000000015116','A mudança de positivo para negativo indica máximo; a inversa indica mínimo.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015116','mínimo local em $x=1$ e máximo local em $x=-1$','Esta questão avalia classificar extremos pelo teste da primeira derivada. A derivada de $f(x)=x^3-3x$ determina onde a função cresce ou decresce. Os números críticos $-1,1$ dividem a reta em intervalos de teste. Use um ponto de cada intervalo ou os fatores da derivada para saber se $f$ cresce ou decresce. Crescer e depois decrescer produz máximo; decrescer e depois crescer produz mínimo. A tabela de sinais fornece: mínimo local em $x=1$ e máximo local em $x=-1$. A conclusão é mínimo local em $x=1$ e máximo local em $x=-1$; os demais resultados correspondem a confundir número crítico com extremo sem testar a mudança de sinal.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000151161','00000043-0000-4000-8000-000000015116','Derive a função','A derivada de $f(x)=x^3-3x$ determina onde a função cresce ou decresce.',1),('00000073-0000-4000-8000-000000151162','00000043-0000-4000-8000-000000015116','Separe os intervalos','Os números críticos $-1,1$ dividem a reta em intervalos de teste.',2),('00000073-0000-4000-8000-000000151163','00000043-0000-4000-8000-000000015116','Analise o sinal','Use um ponto de cada intervalo ou os fatores da derivada para saber se $f$ cresce ou decresce.',3),('00000073-0000-4000-8000-000000151164','00000043-0000-4000-8000-000000015116','Classifique as mudanças','Crescer e depois decrescer produz máximo; decrescer e depois crescer produz mínimo.',4),('00000073-0000-4000-8000-000000151165','00000043-0000-4000-8000-000000015116','Conclua','A tabela de sinais fornece: mínimo local em $x=1$ e máximo local em $x=-1$.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
