insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015122','máximo local em $x=-1$ e mínimo local em $x=3$','Esta questão avalia classificar extremos pelo teste da primeira derivada. A derivada de $f(x)=x^3-3x^2-9x$ determina onde a função cresce ou decresce. Os números críticos $-1,3$ dividem a reta em intervalos de teste. Use um ponto de cada intervalo ou os fatores da derivada para saber se $f$ cresce ou decresce. Crescer e depois decrescer produz máximo; decrescer e depois crescer produz mínimo. A tabela de sinais fornece: máximo local em $x=-1$ e mínimo local em $x=3$. A conclusão é máximo local em $x=-1$ e mínimo local em $x=3$; os demais resultados correspondem a confundir número crítico com extremo sem testar a mudança de sinal.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
