insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('00000043-0000-4000-8000-000000015123','20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000001501','multiple_choice','easy','published','Considere o gráfico vetorial autoral abaixo. [[diagram:curve-01]] Qual descrição de variação é compatível com a curva?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000151231','00000043-0000-4000-8000-000000015123','A','máximo local seguido de mínimo local',1),('00000053-0000-4000-8000-000000151232','00000043-0000-4000-8000-000000015123','B','a função é estritamente crescente em todo o domínio',2),('00000053-0000-4000-8000-000000151233','00000043-0000-4000-8000-000000015123','C','a curva não possui mudança de concavidade',3),('00000053-0000-4000-8000-000000151234','00000043-0000-4000-8000-000000015123','D','o gráfico representa necessariamente uma reta',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
