insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000151231','00000043-0000-4000-8000-000000015123','Leia o gráfico da esquerda para a direita.',1),('00000063-0000-4000-8000-000000151232','00000043-0000-4000-8000-000000015123','Compare a direção da curva antes e depois de cada topo ou vale.',2),('00000063-0000-4000-8000-000000151233','00000043-0000-4000-8000-000000015123','Uma tangente horizontal pode ocorrer onde o sentido de variação muda.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015123','máximo local seguido de mínimo local','Esta questão avalia interpretar crescimento, decrescimento e extremos a partir de um gráfico. O eixo horizontal representa a variável independente e a altura representa o valor da função. A curva mostra que a função cresce, depois decresce e volta a crescer. Onde a curva sobe, $f^{\prime}$ é positiva; onde desce, $f^{\prime}$ é negativa. Uma troca de crescimento para decrescimento sugere máximo; a troca contrária sugere mínimo. A descrição compatível é: máximo local seguido de mínimo local. A conclusão é máximo local seguido de mínimo local; os demais resultados correspondem a desconsiderar a direção da curva ou inferir uma fórmula inexistente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,title,content_markdown,sort_order) values ('00000073-0000-4000-8000-000000151231','00000043-0000-4000-8000-000000015123','Leia os eixos','O eixo horizontal representa a variável independente e a altura representa o valor da função.',1),('00000073-0000-4000-8000-000000151232','00000043-0000-4000-8000-000000015123','Observe a variação','A curva mostra que a função cresce, depois decresce e volta a crescer.',2),('00000073-0000-4000-8000-000000151233','00000043-0000-4000-8000-000000015123','Relacione com derivadas','Onde a curva sobe, $f^{\prime}$ é positiva; onde desce, $f^{\prime}$ é negativa.',3),('00000073-0000-4000-8000-000000151234','00000043-0000-4000-8000-000000015123','Identifique as mudanças','Uma troca de crescimento para decrescimento sugere máximo; a troca contrária sugere mínimo.',4),('00000073-0000-4000-8000-000000151235','00000043-0000-4000-8000-000000015123','Conclua','A descrição compatível é: máximo local seguido de mínimo local.',5) on conflict (id) do update set title=excluded.title,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
