insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015126','dois máximos locais e um mínimo local entre eles','Esta questão avalia interpretar crescimento, decrescimento e extremos a partir de um gráfico. O eixo horizontal representa a variável independente e a altura representa o valor da função. A curva mostra que a inclinação alterna positivo, negativo, positivo, negativo. Onde a curva sobe, $f^{\prime}$ é positiva; onde desce, $f^{\prime}$ é negativa. Uma troca de crescimento para decrescimento sugere máximo; a troca contrária sugere mínimo. A descrição compatível é: dois máximos locais e um mínimo local entre eles. A conclusão é dois máximos locais e um mínimo local entre eles; os demais resultados correspondem a desconsiderar a direção da curva ou inferir uma fórmula inexistente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
