insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015127','máximo local seguido de mínimo local','Esta questão avalia interpretar crescimento, decrescimento e extremos a partir de um gráfico. O eixo horizontal representa a variável independente e a altura representa o valor da função. A curva mostra que a função cresce, depois decresce e volta a crescer. Onde a curva sobe, $f^{\prime}$ é positiva; onde desce, $f^{\prime}$ é negativa. Uma troca de crescimento para decrescimento sugere máximo; a troca contrária sugere mínimo. A descrição compatível é: máximo local seguido de mínimo local. A conclusão é máximo local seguido de mínimo local; os demais resultados correspondem a desconsiderar a direção da curva ou inferir uma fórmula inexistente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
