insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('00000053-0000-4000-8000-000000151421','00000043-0000-4000-8000-000000015142','A','dois máximos locais e um mínimo local entre eles',1),('00000053-0000-4000-8000-000000151422','00000043-0000-4000-8000-000000015142','B','a função é estritamente crescente em todo o domínio',2),('00000053-0000-4000-8000-000000151423','00000043-0000-4000-8000-000000015142','C','a curva não possui mudança de concavidade',3),('00000053-0000-4000-8000-000000151424','00000043-0000-4000-8000-000000015142','D','o gráfico representa necessariamente uma reta',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
