insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('00000063-0000-4000-8000-000000151421','00000043-0000-4000-8000-000000015142','Leia o gráfico da esquerda para a direita.',1),('00000063-0000-4000-8000-000000151422','00000043-0000-4000-8000-000000015142','Compare a direção da curva antes e depois de cada topo ou vale.',2),('00000063-0000-4000-8000-000000151423','00000043-0000-4000-8000-000000015142','Uma tangente horizontal pode ocorrer onde o sentido de variação muda.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('00000043-0000-4000-8000-000000015142','dois máximos locais e um mínimo local entre eles','Esta questão avalia interpretar crescimento, decrescimento e extremos a partir de um gráfico. O eixo horizontal representa a variável independente e a altura representa o valor da função. A curva mostra que a inclinação alterna positivo, negativo, positivo, negativo. Onde a curva sobe, $f^{\prime}$ é positiva; onde desce, $f^{\prime}$ é negativa. Uma troca de crescimento para decrescimento sugere máximo; a troca contrária sugere mínimo. A descrição compatível é: dois máximos locais e um mínimo local entre eles. A conclusão é dois máximos locais e um mínimo local entre eles; os demais resultados correspondem a desconsiderar a direção da curva ou inferir uma fórmula inexistente.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
